void main() {
    vec4 e = explode(vec4(cen, pc.params.x));
    vec3 q = cen + (pos - cen) * (1.0 - clamp(e.y, 0.0, 0.95)) + nrm * e.x;
    vN = nrm;
    vLocal = pos - cen;
    vId = fid;
    vAway = e.x;
    gl_Position = pc.p * pc.m * vec4(q, 1.0);
}
